@@ -21,5 +21,38 @@
 <aside class="side"><div class="card"><div class="card-head"><h3>Tu música</h3><span class="tiny">MP3 · WAV · OGG</span></div><button class="upload" id="uploadBtn"><span class="plus">＋</span><strong>Importa tu canción</strong><small>Elige un archivo de audio</small></button><input id="fileInput" type="file" accept="audio/*"><p class="file-note">Analizamos el <b>ritmo y los cambios de energía</b> para crear un mapa de notas. La detección puede variar según la canción.</p></div>
 <div class="card"><div class="card-head"><h3>Ahora sonando</h3><span class="tiny">DEMO</span></div><div class="track-row"><div class="track-thumb">♫</div><div class="track-info"><strong id="trackName">Midnight City</strong><small id="trackArtist">NEON//BEAT STUDIO</small></div><span class="track-bpm" id="bpmLabel">120 BPM</span></div></div>
 <div class="card"><div class="card-head"><h3>Preferencias</h3><span class="tiny">AJUSTES</span></div><div class="control-row"><label>Velocidad de caída</label><span class="value" id="speedLabel">1.0×</span></div><input class="range" id="speed" type="range" min="0.7" max="1.5" step="0.1" value="1"><div class="control-row" style="margin-top:12px"><label>Sonido de las teclas</label><input class="toggle" id="sfxToggle" type="checkbox" checked></div><div class="control-row"><label>Notas largas</label><input class="toggle" id="longToggle" type="checkbox" checked></div></div>
 <div class="card"><div class="card-head"><h3>Cómo jugar</h3><span class="tiny">RÁPIDO</span></div><div class="howto"><span><b>A</b> · 1</span><span><b>S</b> · 2</span><span><b>D</b> · 3</span><span><b>F</b> · 4</span></div><p class="file-note">Toca la nota justo en la línea. Mantén pulsado para las notas largas. ¡Construye tu combo!</p></div></aside></main></div><div class="toast" id="toast"></div>
+<audio id="audio" preload="auto"></audio>
 <script>
+const $=s=>document.querySelector(s), board=$('#board'), layer=$('#noteLayer'), overlay=$('#overlay');
+let ctx=null, audio=$('#audio'), track='demo', chart=[], notes=[], running=false, startedAt=0, elapsed=0, duration=60, score=0, combo=0, hits=0, judged=0, held=new Set(), sourceNodes=[], muted=false, speed=1, raf=0, toastTimer;
+const laneColors=['#ff4db8','#a36bff','#54e8ef','#c8f36a'], laneKeys=['a','s','d','f'];
+function audioCtx(){if(!ctx)ctx=new(window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();return ctx}
+function showToast(msg){const t=$('#toast');t.innerHTML=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}
+function fmt(t){t=Math.max(0,Math.floor(t));return `${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`}
+function updateStats(){ $('#score').textContent=String(score).padStart(6,'0');$('#combo').textContent='×'+combo;$('#accuracy').textContent=(judged?Math.round(hits/judged*100):100)+'%'; }
+function setTrackUI(name,sub,bpm,dur){$('#songTitle').textContent=name;$('#songSub').textContent=sub;$('#trackName').textContent=name;$('#trackArtist').textContent=sub.split(' · ')[0]||'TU BIBLIOTECA';$('#bpmLabel').textContent=bpm+' BPM';$('#duration').textContent=fmt(dur)}
+function buildDemo(){duration=60;const bpm=120,beat=60/bpm;chart=[];let i=0;for(let t=1.2;t<duration-1;t+=beat){if(i%8===6){chart.push({time:t,lane:(i*3+1)%4,duration:1.05,type:'long'})}else if(i%4!==3||Math.random()>.35){chart.push({time:t,lane:(i*7+Math.floor(i/4))%4,duration:0,type:'normal'})}if(i%8===2)chart.push({time:t+beat/2,lane:(i+2)%4,duration:0,type:'normal'});i++}setTrackUI('Midnight City (demo)','NEON//BEAT STUDIO · 120 BPM',120,duration)}
+function playTone(freq,when,dur,type='sine',vol=.08){if(muted||!ctx)return;let o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,when);g.gain.setValueAtTime(vol,when);g.gain.exponentialRampToValueAtTime(.001,when+dur);o.connect(g);g.connect(ctx.destination);o.start(when);o.stop(when+dur+.02);sourceNodes.push(o)}
+function demoSound(t){const c=audioCtx(),beat=.5;let b=Math.floor(t/beat),phase=t%beat;if(phase<.055){let when=c.currentTime-phase;if(b%4===0)playTone(66,when,.22,'sine',.22);else if(b%4===2)playTone(165,when,.11,'triangle',.11);playTone(9000,when,.025,'square',.012);if(b%2===1)playTone([220,246.94,196,164.81][Math.floor(b/4)%4],when,.22,'triangle',.035)}if(phase>.24&&phase<.29&&b%2===1)playTone(7000,c.currentTime-(phase-.25),.025,'square',.008)}
+function begin(){if(running)return;audioCtx();if(elapsed>=duration){elapsed=0;score=combo=hits=judged=0;notes=[];updateStats()}running=true;startedAt=performance.now()/1000-elapsed;if(track==='file'&&audio.src){audio.currentTime=elapsed;audio.play().catch(()=>{});}overlay.classList.add('hidden');$('#startBtn').textContent='CONTINUAR →';lastFrame=0;raf=requestAnimationFrame(loop)}
+function stopAudio(){audio.pause();for(const n of sourceNodes){try{n.stop()}catch(e){}}sourceNodes=[]}
+function pause(){if(!running)return;elapsed=getElapsed();running=false;cancelAnimationFrame(raf);audio.pause();overlay.classList.remove('hidden');$('#overlayTitle').textContent='Pausa';$('#overlayText').textContent='Tu partida está en pausa.';$('#startBtn').textContent='CONTINUAR →'}
+function reset(){running=false;cancelAnimationFrame(raf);stopAudio();elapsed=0;score=combo=hits=judged=0;notes=[];layer.innerHTML='';updateStats();$('#progressBar').style.width='0%';$('#currentTime').textContent='0:00';overlay.classList.remove('hidden');$('#overlayTitle').textContent='¿Listo para jugar?';$('#overlayText').textContent='Pulsa las notas cuando lleguen a la línea.';$('#startBtn').textContent='EMPEZAR A JUGAR  →'}
+function getElapsed(){return track==='file'&&audio.src?audio.currentTime:performance.now()/1000-startedAt}
+let lastFrame=0;
+function loop(now){if(!running)return;elapsed=getElapsed();if(track==='demo')demoSound(elapsed);const h=board.clientHeight,target=h-66-32,px=170*speed,travel=target/px+0.12;
+  for(const n of chart){if(!n.spawned&&n.time-elapsed<=travel&&n.time-elapsed>-1){n.spawned=true;const el=document.createElement('div');el.className='tile '+n.type;el.style.setProperty('--tile',laneColors[n.lane]);el.style.setProperty('--glow',laneColors[n.lane]+'55');el.dataset.id=n.id;layer.appendChild(el);n.el=el}}
+  for(const n of chart){if(!n.spawned||n.done||!n.el)continue;const height=n.type==='long'?Math.max(58,n.duration*px):65;const y=target-(n.time-elapsed)*px-height;n.el.style.left=`calc(${n.lane*25}% + 5px)`;n.el.style.width='calc(25% - 10px)';n.el.style.height=height+'px';n.el.style.top=y+'px';if(y>h-65){miss(n)} }
+  if(track==='file'&&audio.ended){finish();return}if(elapsed>=duration){finish();return}$('#currentTime').textContent=fmt(elapsed);$('#progressBar').style.width=Math.min(100,elapsed/duration*100)+'%';raf=requestAnimationFrame(loop)}
+function miss(n){n.done=true;if(n.el)n.el.remove();combo=0;judged++;updateStats()}
+function hitLane(lane,down){const btn=document.querySelector(`.key[data-lane="${lane}"]`);if(down){held.add(lane);btn?.classList.add('active');if(!running)return;let t=getElapsed(),cand=chart.filter(n=>!n.done&&n.lane===lane&&Math.abs(n.time-t)<.23).sort((a,b)=>Math.abs(a.time-t)-Math.abs(b.time-t))[0];if(!cand){playHit(lane,false);return}cand.done=true;if(cand.el){cand.el.classList.add('hit');setTimeout(()=>cand.el?.remove(),100)}const delta=Math.abs(cand.time-t),points=delta<.08?300:delta<.15?180:100;score+=points+Math.min(combo,30)*5;combo++;hits++;judged++;updateStats();playHit(lane,true);showToast(delta<.08?'<b>PERFECT!</b> +'+points:delta<.15?'<b>GREAT!</b> +'+points:'<b>GOOD</b> +'+points);if(cand.type==='long')cand.holdUntil=cand.time+cand.duration;
+ }else{held.delete(lane);btn?.classList.remove('active')}}
+function playHit(lane,good){if(!$('#sfxToggle').checked)return;audioCtx();playTone([440,523,659,784][lane],ctx.currentTime,.11,'sine',good?.075:.03)}
+function finish(){running=false;elapsed=duration;cancelAnimationFrame(raf);audio.pause();overlay.classList.remove('hidden');$('#overlayTitle').textContent='¡Canción completada!';$('#overlayText').textContent=`${score.toLocaleString('es')} puntos · ${judged?Math.round(hits/judged*100):100}% de precisión`;$('#startBtn').textContent='JUGAR OTRA VEZ  ↺';notes=[];updateStats()}
+function keyEvent(e,down){let k=e.key.toLowerCase(),lane=laneKeys.indexOf(k);if(lane<0)return;if(e.repeat)return;e.preventDefault();hitLane(lane,down)}window.addEventListener('keydown',e=>keyEvent(e,true));window.addEventListener('keyup',e=>keyEvent(e,false));window.addEventListener('blur',()=>{held.clear();document.querySelectorAll('.key.active').forEach(x=>x.classList.remove('active'))});document.querySelectorAll('.key').forEach(b=>{let lane=+b.dataset.lane;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);hitLane(lane,true)});b.addEventListener('pointerup',()=>hitLane(lane,false));b.addEventListener('pointercancel',()=>hitLane(lane,false))});
+$('#startBtn').addEventListener('click',()=>{if(elapsed>=duration)reset();begin()});$('#pauseBtn').addEventListener('click',pause);$('#restartBtn').addEventListener('click',()=>{reset();begin()});$('#volumeBtn').addEventListener('click',()=>{muted=!muted;$('#volumeBtn').textContent=muted?'♫̸':'♫';audio.muted=muted});$('#speed').addEventListener('input',e=>{speed=+e.target.value;$('#speedLabel').textContent=speed.toFixed(1)+'×'});
+$('#uploadBtn').addEventListener('click',()=>$('#fileInput').click());$('#fileInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;reset();try{showToast('Analizando ritmo…');const c=audioCtx(),buf=await c.decodeAudioData(await file.arrayBuffer());duration=buf.duration;const bpmData=analyze(buf);chart=bpmData.events.map((n,i)=>({...n,id:i,spawned:false,done:false}));track='file';audio.src=URL.createObjectURL(file);audio.load();const name=file.name.replace(/\.[^.]+$/,'');setTrackUI(name,'TU BIBLIOTECA · RITMO DETECTADO',bpmData.bpm,duration);$('#overlayText').textContent=`Ritmo aproximado: ${bpmData.bpm} BPM · ${chart.length} notas detectadas`;$('#duration').textContent=fmt(duration);showToast(`<b>¡Lista!</b> ${bpmData.bpm} BPM estimados`)}catch(err){console.error(err);showToast('No se pudo analizar este archivo. Prueba otro formato.')}});
+function analyze(buf){const data=buf.getChannelData(0),sr=buf.sampleRate,win=1024,step=512,energy=[];for(let p=0;p<data.length;p+=step){let sum=0,end=Math.min(data.length,p+win);for(let i=p;i<end;i+=4)sum+=data[i]*data[i];energy.push(Math.sqrt(sum/Math.max(1,(end-p)/4)))}const flux=energy.map((v,i)=>Math.max(0,v-(energy[i-1]||0))),sorted=[...flux].sort((a,b)=>a-b),threshold=Math.max(sorted[Math.floor(sorted.length*.72)]||.01,.003),minGap=Math.round(.22*sr/step),peaks=[];for(let i=2;i<flux.length-2;i++){if(flux[i]>threshold&&flux[i]>=flux[i-1]&&flux[i]>flux[i+1]&&(peaks.length===0||i-peaks[peaks.length-1]>=minGap))peaks.push(i)}let times=peaks.map(i=>i*step/sr).filter(t=>t>.25&&t<buf.duration-.15);if(times.length<8){times=[];for(let t=.6;t<buf.duration;t+=.5)times.push(t)}const intervals=[];for(let i=1;i<times.length;i++){let d=times[i]-times[i-1];if(d>.24&&d<1.1)intervals.push(d)}let bpm=intervals.length?Math.round(60/(intervals.sort((a,b)=>a-b)[Math.floor(intervals.length/2)])):120;while(bpm<70)bpm*=2;while(bpm>180)bpm/=2;bpm=Math.round(bpm);let events=times.map((t,i)=>{let energyAt=energy[Math.min(energy.length-1,Math.floor(t*sr/step))]||0;let sustained=energy.slice(Math.floor(t*sr/step),Math.floor((t+.65)*sr/step)).filter(x=>x>energyAt*.55).length;let lng=$('#longToggle').checked&&sustained>Math.max(4,Math.floor(.65*sr/step)*.55)&&i%4===1;return{time:t,lane:(i*7+Math.floor(i/3))%4,type:lng?'long':'normal',duration:lng?.75:0,spawned:false,done:false}});return{bpm,events}}
+$('#sfxToggle').addEventListener('change',()=>{});$('#longToggle').addEventListener('change',()=>{});buildDemo();updateStats();
+</script></body></html>

